changeSet.sql:
CREATE TABLE IF NOT EXISTS "user".white_list
(
    id                 UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    from_user          UUID NOT NULL,
    to_user            UUID NOT NULL,
    for_type           TEXT NOT NULL,
    created_date       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_white_list_from ON "user".white_list (from_user);
CREATE INDEX IF NOT EXISTS idx_white_list_to ON "user".white_list (to_user);
